import { resolveIn } from './resolve-in.ts';
import type tokensFile from './tokens.json';

export type TokensFile = typeof tokensFile;

type Leaves = Record<string, { $value: string }>;

const HEADER =
  'GENERATED by scripts/build-tokens.ts from tokens.json. Do not edit; run `npm run tokens:build`.';

/** Resolved `{ name: value }` for a group of `{ $value }` leaves. */
function resolved(root: TokensFile, group: string, leaves: Leaves): [string, string][] {
  return Object.keys(leaves).map((name) => [name, resolveIn(root, `${group}.${name}`)]);
}

function palette(root: TokensFile): [string, string][] {
  const rows: [string, string][] = [];
  for (const [scale, steps] of Object.entries(root.palette)) {
    for (const step of Object.keys(steps)) {
      rows.push([`${scale}-${step}`, resolveIn(root, `palette.${scale}.${step}`)]);
    }
  }
  return rows;
}

/** Turns tokens.json into the CSS (Tailwind v4 theme) and the typed TS module. Pure and deterministic. */
export function generateTokens(root: TokensFile): { css: string; ts: string } {
  const colors = resolved(root, 'color', root.color);
  const tvColors = resolved(root, 'tv.color', root.tv.color);
  const shadcn = resolved(root, 'shadcn', root.shadcn);
  const lines: string[] = [];
  const add = (...rows: string[]): void => {
    lines.push(...rows);
  };

  add(
    `/* ${HEADER} */`,
    '',
    ':root {',
    '  /* Raw palette. It has no utility classes: components use the role tokens below. */',
  );
  for (const [name, value] of palette(root)) add(`  --palette-${name}: ${value};`);
  add(
    '}',
    '',
    '@theme {',
    "  /* Only our colours exist: Tailwind's default palette is switched off. */",
    '  --color-*: initial;',
  );

  add('', '  /* Role colours (what components use) */');
  for (const [name, value] of colors) add(`  --color-${name}: ${value};`);
  add(
    '',
    '  /* shadcn/ui names, mapped to our roles so components added with its CLI pick up our theme */',
  );
  for (const [name, value] of shadcn) add(`  --color-${name}: ${value};`);
  add('', '  /* TV display colours */');
  for (const [name, value] of tvColors) add(`  --color-tv-${name}: ${value};`);

  add(
    '',
    '  /* Type */',
    `  --font-sans: ${root.font.sans.$value};`,
    `  --default-font-feature-settings: ${root.font.features.$value};`,
    '  --text-*: initial;',
  );
  for (const [name, style] of Object.entries(root.text)) {
    add(
      `  --text-${name}: ${style.size};`,
      `  --text-${name}--line-height: ${style.lineHeight};`,
      `  --text-${name}--font-weight: ${style.weight};`,
    );
  }
  for (const [name, value] of Object.entries(root.tv.text)) {
    add(
      `  --text-tv-${name}: ${value};`,
      `  --text-tv-${name}--line-height: 1.1;`,
      `  --text-tv-${name}--font-weight: 700;`,
    );
  }

  add('', '  /* Shape */', '  --radius-*: initial;');
  for (const [name, value] of resolved(root, 'radius', root.radius))
    add(`  --radius-${name}: ${value};`);
  add('  --radius-full: 9999px;', '  --shadow-*: initial;');
  for (const [name, value] of resolved(root, 'shadow', root.shadow))
    add(`  --shadow-${name}: ${value};`);

  add(
    '',
    '  /* Sizes: control heights and the minimum touch target (usable as h-control-md, min-h-target, ...) */',
  );
  for (const [name, value] of Object.entries(root.size)) {
    const prefix =
      name.startsWith('control') || name === 'target-min' ? '--spacing-' : '--container-';
    add(`  ${prefix}${name === 'target-min' ? 'target' : name}: ${value};`);
  }

  add(
    '',
    '  /* Layout: breakpoints in em so zooming triggers the smaller layout */',
    '  --breakpoint-*: initial;',
  );
  for (const [name, value] of Object.entries(root.breakpoint))
    add(`  --breakpoint-${name}: ${value};`);

  add(
    '',
    '  /* Motion */',
    `  --default-transition-duration: ${root.motion['duration-fast']};`,
    '}',
    '',
  );

  const css = lines.join('\n');
  const data = {
    palette: Object.fromEntries(palette(root)),
    color: Object.fromEntries(colors),
    tvColor: Object.fromEntries(tvColors),
    text: root.text,
    tvText: root.tv.text,
    radius: Object.fromEntries(resolved(root, 'radius', root.radius)),
    shadow: Object.fromEntries(resolved(root, 'shadow', root.shadow)),
    size: root.size,
    breakpoint: root.breakpoint,
  };
  const ts = [
    `// ${HEADER}`,
    '',
    `export const tokens = ${JSON.stringify(data, null, 2)} as const;`,
    '',
    'export type ColorRole = keyof typeof tokens.color;',
    'export type TvColorRole = keyof typeof tokens.tvColor;',
    '',
  ].join('\n');
  return { css, ts };
}
